  it("shows empty lists on first open", async () => {
    const html = await (await fetch(base + "/")).text();
    expect(html).toContain("Currently reading");
    expect(html).toContain("Nothing on the go.");
    expect(html).toContain("Nothing finished yet.");
  });

  it("adds a book, shows its page, marks it finished", async () => {
    const res = await post("/books", { title: "Dune", author: "Frank Herbert", notes: "Spice & sand" });
    expect(res.status).toBe(303);

    const [book] = JSON.parse(await readFile(file, "utf8"));
    expect(book).toMatchObject({ title: "Dune", author: "Frank Herbert", notes: "Spice & sand", finishedAt: null });

    const detail = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(detail).toContain("Dune");
    expect(detail).toContain("Frank Herbert");
    expect(detail).toContain("Spice &amp; sand");

    const fin = await post(`/books/${book.id}/finish`, {}, { Referer: `${base}/books/${book.id}` });
    expect(fin.status).toBe(303);
    expect(fin.headers.get("location")).toBe(`/books/${book.id}`);

    const home = await (await fetch(base + "/")).text();
    expect(home).toContain("Nothing on the go.");
    expect(home.split("<h2>Finished</h2>")[1]).toContain("Dune");
  });

  it("keeps books across a restart", async () => {
    await post("/books", { title: "Emma", author: "Jane Austen" });
    await stop();
    await start();
    expect(await (await fetch(base + "/")).text()).toContain("Emma");
  });

