      const { pathname } = new URL(req.url, "http://localhost");
      const bookMatch = pathname.match(/^\/books\/([\w-]+)$/);
      const finishMatch = pathname.match(/^\/books\/([\w-]+)\/finish$/);

      if (req.method === "GET" && pathname === "/") return send(200, homePage(store.all()));

      if (req.method === "POST" && pathname === "/books") {
        const form = await readForm(req);
        const values = {
          title: (form.get("title") ?? "").trim(),
          author: (form.get("author") ?? "").trim(),
          notes: (form.get("notes") ?? "").trim(),
        };
        if (!values.title || !values.author) {
          return send(400, homePage(store.all(), { error: "Title and author are required.", values }));
        }
        await store.add(values);
        return redirect("/");
      }

      if (req.method === "GET" && bookMatch) {
        const book = store.get(bookMatch[1]);
        return book ? send(200, bookPage(book)) : notFound();
      }

      if (req.method === "POST" && finishMatch) {
        const book = await store.finish(finishMatch[1]);
        if (!book) return notFound();
        // Go back to whichever page the button was on.
        const back = req.headers.referer && new URL(req.headers.referer).pathname === `/books/${book.id}` ? `/books/${book.id}` : "/";
        return redirect(back);
      }

      return send(404, page("Not found", `<p>Page not found.</p><p><a href="/">&larr; All books</a></p>`));
    } catch (err) {
      const status = err.status ?? 500;
      if (status === 500) console.error(err);
      if (!res.headersSent) send(status, page("Error", `<p>Something went wrong.</p>`));
    }
  });
}

